#include <iostream>
using namespace std;

namespace kitchen {
    int fish = 9;
}

namespace pond {
    int fish = 2;
}

int main() {
    int borrow = 0;
    cin >> borrow;

    kitchen::fish = kitchen::fish - borrow;
    pond::fish = pond::fish + borrow;

    cout << "kitchen 还剩 " << kitchen::fish << " 条喵" << endl;
    cout << "pond 现在有 " << pond::fish << " 条喵" << endl;
    return 0;
}

